create extension if not exists "pgcrypto";

create type public.app_role as enum ('customer','admin');
create type public.product_status as enum ('draft','published','archived');

create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, role app_role not null default 'customer', created_at timestamptz not null default now());
create table public.brands (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, logo_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.fragrance_families (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text);
create table public.fragrance_notes (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique);
create table public.perfumes (id uuid primary key default gen_random_uuid(), brand_id uuid not null references public.brands, family_id uuid references public.fragrance_families, name text not null, slug text not null unique, description text not null default '', gender text not null check(gender in ('femenino','masculino','unisex')), concentration text not null, status product_status not null default 'draft', featured boolean not null default false, is_new boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.perfume_variants (id uuid primary key default gen_random_uuid(), perfume_id uuid not null references public.perfumes on delete cascade, size_ml integer not null check(size_ml>0), price numeric(12,2) not null check(price>=0), sale_price numeric(12,2) check(sale_price>=0 and sale_price<price), stock integer not null default 0 check(stock>=0), low_stock_threshold integer not null default 3, sku text unique, unique(perfume_id,size_ml));
create table public.perfume_images (id uuid primary key default gen_random_uuid(), perfume_id uuid not null references public.perfumes on delete cascade, storage_path text not null, alt_text text not null default '', is_primary boolean not null default false, display_order integer not null default 0);
create table public.perfume_notes (perfume_id uuid not null references public.perfumes on delete cascade, note_id uuid not null references public.fragrance_notes, stage text not null check(stage in ('top','heart','base','accord')), display_order integer not null default 0, primary key(perfume_id,note_id,stage));
create table public.collections (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', cover_path text, status product_status not null default 'draft', display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.collection_items (collection_id uuid not null references public.collections on delete cascade, perfume_id uuid not null references public.perfumes on delete cascade, display_order integer not null default 0, primary key(collection_id,perfume_id));
create table public.wishlists (user_id uuid not null references auth.users on delete cascade, perfume_id uuid not null references public.perfumes on delete cascade, created_at timestamptz not null default now(), primary key(user_id,perfume_id));
create table public.inquiries (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete set null, customer_name text, customer_phone text, status text not null default 'draft', estimated_total numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table public.inquiry_items (id uuid primary key default gen_random_uuid(), inquiry_id uuid not null references public.inquiries on delete cascade, variant_id uuid not null references public.perfume_variants, quantity integer not null check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0));
create table public.inventory_movements (id uuid primary key default gen_random_uuid(), variant_id uuid not null references public.perfume_variants, delta integer not null check(delta<>0), reason text not null, created_by uuid not null references auth.users, created_at timestamptz not null default now());
create table public.site_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create index perfumes_public_idx on public.perfumes(status,display_order); create index variants_perfume_idx on public.perfume_variants(perfume_id); create index notes_perfume_idx on public.perfume_notes(perfume_id); create index collection_order_idx on public.collection_items(collection_id,display_order);

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.brands enable row level security; alter table public.fragrance_families enable row level security; alter table public.fragrance_notes enable row level security; alter table public.perfumes enable row level security; alter table public.perfume_variants enable row level security; alter table public.perfume_images enable row level security; alter table public.perfume_notes enable row level security; alter table public.collections enable row level security; alter table public.collection_items enable row level security; alter table public.wishlists enable row level security; alter table public.inquiries enable row level security; alter table public.inquiry_items enable row level security; alter table public.inventory_movements enable row level security; alter table public.site_settings enable row level security;
create policy "published perfumes public" on public.perfumes for select using(status='published' or is_admin());
create policy "published collections public" on public.collections for select using(status='published' or is_admin());
create policy "public reference data" on public.brands for select using(true); create policy "public families" on public.fragrance_families for select using(true); create policy "public notes" on public.fragrance_notes for select using(true);
create policy "public variants of published" on public.perfume_variants for select using(exists(select 1 from public.perfumes p where p.id=perfume_id and (p.status='published' or is_admin())));
create policy "public images of published" on public.perfume_images for select using(exists(select 1 from public.perfumes p where p.id=perfume_id and (p.status='published' or is_admin())));
create policy "own profile" on public.profiles for select using(id=auth.uid() or is_admin()); create policy "own wishlist" on public.wishlists for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own inquiries" on public.inquiries for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create policy "admin perfumes" on public.perfumes for all using(is_admin()) with check(is_admin()); create policy "admin variants" on public.perfume_variants for all using(is_admin()) with check(is_admin()); create policy "admin images" on public.perfume_images for all using(is_admin()) with check(is_admin()); create policy "admin collections" on public.collections for all using(is_admin()) with check(is_admin()); create policy "admin inventory" on public.inventory_movements for all using(is_admin()) with check(is_admin()); create policy "admin settings" on public.site_settings for all using(is_admin()) with check(is_admin());
create policy "admin brands" on public.brands for all using(is_admin()) with check(is_admin()); create policy "admin families" on public.fragrance_families for all using(is_admin()) with check(is_admin()); create policy "admin notes" on public.fragrance_notes for all using(is_admin()) with check(is_admin()); create policy "admin perfume notes" on public.perfume_notes for all using(is_admin()) with check(is_admin()); create policy "admin collection items" on public.collection_items for all using(is_admin()) with check(is_admin());

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('perfume-images','perfume-images',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do nothing;
create policy "public perfume images" on storage.objects for select using(bucket_id='perfume-images'); create policy "admin uploads" on storage.objects for insert with check(bucket_id='perfume-images' and public.is_admin()); create policy "admin image updates" on storage.objects for update using(bucket_id='perfume-images' and public.is_admin()); create policy "admin image deletes" on storage.objects for delete using(bucket_id='perfume-images' and public.is_admin());
